// ─────────────────────────────────────────────────────────────────────────────
// `reverse` — reverses a list.
//
// Scheme semantics: (reverse list) → a new list with elements in reverse order.
// // ─────────────────────────────────────────────────────────────────────────────

declare function reverse<T>(xs: List<T>): List<T>;
